package local.chatagent.privatechat;
import android.app.*;import android.content.Context;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
final class RegionPicker {
 interface Picked{void accept(String value);}
 static void show(Activity activity,String original,Picked picked){try{
  ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=activity.getAssets().open("regions.json")){byte[] buffer=new byte[8192];int count;while((count=input.read(buffer))!=-1)bytes.write(buffer,0,count);}JSONArray data=new JSONArray(bytes.toString("UTF-8"));
  int padding=(int)(20*activity.getResources().getDisplayMetrics().density);LinearLayout body=new LinearLayout(activity);body.setOrientation(1);body.setPadding(padding,padding,padding,padding);
  TextView countryLabel=new TextView(activity);countryLabel.setText("国家 / 地区");body.addView(countryLabel);Spinner countries=new Spinner(activity,Spinner.MODE_DIALOG);countries.setPrompt("选择国家 / 地区");body.addView(countries,new LinearLayout.LayoutParams(-1,-2));TextView provinceLabel=new TextView(activity);provinceLabel.setText("省 / 州 / 地区");body.addView(provinceLabel);Spinner regions=new Spinner(activity,Spinner.MODE_DIALOG);regions.setPrompt("选择省 / 州 / 地区");body.addView(regions,new LinearLayout.LayoutParams(-1,-2));
  List<String> names=new ArrayList<>();names.add("请选择国家 / 地区");int selected=0,selectedRegion=0;for(int i=0;i<data.length();i++){JSONObject c=data.getJSONObject(i);String name=c.getString("name");names.add(name);if(original.equals(name)){selected=i+1;}JSONArray items=c.getJSONArray("regions");for(int j=0;j<items.length();j++)if(original.equals(name+" · "+items.getString(j))){selected=i+1;selectedRegion=j+1;}}
  ArrayAdapter<String> countryAdapter=new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,names);countries.setAdapter(countryAdapter);final int[] current={selected};fill(activity,data,regions,selected);regions.setSelection(selectedRegion);countries.setSelection(selected);
  countries.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long row){if(current[0]!=position){current[0]=position;fill(activity,data,regions,position);}}});
  AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("所在地区").setView(body).setNegativeButton("取消",null).setNeutralButton("不显示地区",(d,n)->picked.accept("")).setPositiveButton("确定",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{int i=countries.getSelectedItemPosition();if(i==0){Toast.makeText(activity,"请选择国家或地区",Toast.LENGTH_SHORT).show();return;}try{String value=data.getJSONObject(i-1).getString("name");if(regions.getSelectedItemPosition()>0)value+=" · "+regions.getSelectedItem();picked.accept(value);dialog.dismiss();}catch(Exception ignored){}}));dialog.show();
 }catch(Exception e){Toast.makeText(activity,"地区选项暂时无法打开",Toast.LENGTH_LONG).show();}}
 private static void fill(Context context,JSONArray data,Spinner spinner,int index){List<String> list=new ArrayList<>();list.add("请选择省 / 州 / 地区");try{if(index>0){JSONArray regions=data.getJSONObject(index-1).getJSONArray("regions");for(int j=0;j<regions.length();j++)list.add(regions.getString(j));}}catch(Exception ignored){}spinner.setAdapter(new ArrayAdapter<>(context,android.R.layout.simple_spinner_dropdown_item,list));spinner.setEnabled(list.size()>1);}
}
